def without_pointers(value,paths):
    parsed=[]
    for path in paths:
        path=text(path,'ignore_pointer')
        if not path.startswith('/') or path=='/':raise E('ignore pointer must be a non-root JSON pointer')
        raw_parts=path[1:].split('/');parts=[]
        for raw in raw_parts:
